// Source-derived string boundary inventory.
fn capture_typed_strings(name:&str,raw:&str)->Result<std::collections::BTreeMap<String,Vec<u16>>,serde_json::Error>{
 match name {
 "ClearinghouseState"=>capture_strings::<safe_cex_venue_hyperliquid::types::ClearinghouseState>(raw),
 "UserFills"=>capture_strings::<safe_cex_venue_hyperliquid::types::UserFills>(raw),
 "WsTrade"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsTrade>(raw),
 "WsBook"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsBook>(raw),
 "WsBbo"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsBbo>(raw),
 "WsLevel"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsLevel>(raw),
 "WsOrder"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsOrder>(raw),
 "WsFill"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsFill>(raw),
 "WsUserFunding"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsUserFunding>(raw),
 "WsLiquidation"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsLiquidation>(raw),
 "WsNonUserCancel"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsNonUserCancel>(raw),
 "L2Book"=>capture_strings::<safe_cex_venue_hyperliquid::types::L2Book>(raw),
 "FundingHistoryEntry"=>capture_strings::<safe_cex_venue_hyperliquid::types::FundingHistoryEntry>(raw),
 "FundingHistory"=>capture_strings::<safe_cex_venue_hyperliquid::types::FundingHistory>(raw),
 "UserOpenOrder"=>capture_strings::<safe_cex_venue_hyperliquid::types::UserOpenOrder>(raw),
 "UserOpenOrders"=>capture_strings::<safe_cex_venue_hyperliquid::types::UserOpenOrders>(raw),
 "CancelOrderRequest"=>capture_strings::<safe_cex_venue_hyperliquid::types::CancelOrderRequest>(raw),
 "Signature"=>capture_strings::<safe_cex_venue_hyperliquid::types::Signature>(raw),
 "Candle"=>capture_strings::<safe_cex_venue_hyperliquid::types::Candle>(raw),
 "HyperliquidCandle"=>capture_strings::<safe_cex_venue_hyperliquid::types::HyperliquidCandle>(raw),
 "WsUserFill"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsUserFill>(raw),
 "WsUserFills"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsUserFills>(raw),
 "WsUserFundings"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsUserFundings>(raw),
 "WsUserNonFundingLedgerUpdate"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsUserNonFundingLedgerUpdate>(raw),
 "WsUserNonFundingLedgerUpdates"=>capture_strings::<safe_cex_venue_hyperliquid::types::WsUserNonFundingLedgerUpdates>(raw),
 "BuilderInfo"=>capture_strings::<safe_cex_venue_hyperliquid::types::BuilderInfo>(raw),
 _=>panic!("unrecognized source string-bearing numeric type {name}"),
 }
}
